    pub const fn from_coeffs(c: [S::Arr<T>; 3]) -> Self {
        OriginPlane { o: core::marker::PhantomData, c }
    }

    /// All coefficients zero.
    #[inline(always)]
    pub fn zero() -> Self {
        OriginPlane { o: core::marker::PhantomData, c: [S::from_flat(&mut |_| T::zero(), 0); 3] }
    }

